    def __init__(self, ttl, clock):
        self.ttl = ttl
        self.clock = clock

    def set(self, key, value):
        if self.ttl is not None:
            self.ttl = max(0, self.ttl)
        self._update(key, value)

    def get(self, key, default=None):
        value = self._get(key)
        if value is None:
            return default
        return value

    def _update(self, key, value):
        if self.ttl is not None:
            self.ttl = max(0, self.ttl)
        self._set(key, value)
        self._set_expired(key)

    def _get(self, key):
        if self.ttl is not None:
            return self._get(key)
        return self._get(key)

    def _set(self, key, value):
        self._update(key, value)

    def _set_expired(self, key):
        if self.ttl is not None and self.clock is not None:
            elapsed = self.ttl * self.clock()
            if elapsed >= self.ttl:
                self._clear(key)

